mapper.select:
    	SELECT COUNT(1)
    	FROM REP_REVEAL
    	WHERE 1=1

			AND REP_ID = #{tabNum,jdbcType=VARCHAR}


			AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


			AND PRODID = #{PROD_ID,jdbcType=VARCHAR}


			AND START_DATE = to_date(#{START_DATE,jdbcType=VARCHAR},'yyyy-mm-dd')


			AND END_DATE = to_date(#{END_DATE,jdbcType=VARCHAR},'yyyy-mm-dd')

		AND STATUS='E'
		AND CONFIRM_STATUS='1'

        SELECT 
			count(1) 
		FROM 
			REP_REVEAL
		WHERE
			REP_ID = #{tabNum,jdbcType=VARCHAR}
		AND nvl2(PRODID,PRODID,'0') = #{PROD_ID,jdbcType=VARCHAR}
		AND nvl2(TO_CHAR(START_DATE,'yyyy-mm-dd'),TO_CHAR(START_DATE,'yyyy-mm-dd'),'0') = #{START_DATE,jdbcType=VARCHAR}
		AND nvl2(TO_CHAR(END_DATE,'yyyy-mm-dd'),TO_CHAR(END_DATE,'yyyy-mm-dd'),'0') = #{END_DATE,jdbcType=VARCHAR}
		AND STATUS='E'
